script:
// The model behind Fig 1: one Enterprise table on a three-instance cluster,
//   trades(ts TIMESTAMP, symbol SYMBOL INDEX, price DOUBLE, amount DOUBLE, venue VARCHAR)
// with a storage policy whose stages are independent of each other. The default is the
// common shape: PARTITION BY DAY with TO REMOTE 1 HOUR, TO PARQUET 3 DAYS, DROP LOCAL 1 MONTH.
//
// A stage is due once partition_end < min(now, latest_ts) - TTL (with live ingestion
// latest_ts is about now). Each instance runs its own storage policy check every 5
// minutes, so it acts at its first check after that (StoragePolicyCheckJob.walkPartitions):
//   TO REMOTE   only the cold storage manager (here replica 2) uploads a Parquet snapshot,
//               once for the whole cluster. Every instance keeps its local copy as it is.
//   TO PARQUET  every instance converts its own local copy.
//   DROP LOCAL  the primary emits PARTITION_SEAL into the WAL, which replicates like any
//               WAL through the object store; the manager marks the copy Sealed; then each
//               instance drops its local data and keeps only _pm and the symbol index.
// Replication itself is continuous: the primary uploads WAL segments to the object store
// within seconds and the replicas download them; no schedule.
//
// Time u is measured in partition widths: partition p covers [p, p + 1). Every
// animation is a pure function of u, so pause, skip and replay are exact.

const PRESETS = {
  HOUR: {
    name: "HOUR", minutes: 60, a0: 0.5, start: 48.35,
    stages: [["TO REMOTE", "1 HOUR", "1h"], ["TO PARQUET", "6 HOURS", "6h"], ["DROP LOCAL", "1 DAY", "1d"]],
  },
  DAY: {
    name: "DAY", minutes: 1440, a0: 0.25, start: 60.3,
    stages: [["TO REMOTE", "1 HOUR", "1h"], ["TO PARQUET", "3 DAYS", "3d"], ["DROP LOCAL", "1 MONTH", "1M"]],
  },
  MONTH: {
    name: "MONTH", minutes: 43830, a0: 0.25, start: 24.3,
    stages: [["TO REMOTE", "1 DAY", "1d"], ["TO PARQUET", "1 MONTH", "1M"], ["DROP LOCAL", "1 YEAR", "1Y"]],
  },
};
const GRAIN_ORDER = ["HOUR", "DAY", "MONTH"];
const policySql = (g) => "PARTITION BY " + g + " · STORAGE POLICY(" + PRESETS[g].stages.map(([s, t]) => s + " " + t).join(", ") + ")";

const INSTANCES = [
  { name: "primary", check: 0.4 },
  { name: "replica 1", check: 2.2 },
  { name: "replica 2", check: 3.9, manager: true },
];
const PRIMARY = 0;
const MANAGER = 2;
// Which instances a figure shows, as indices into INSTANCES and the bench slots, and which
// one holds the cold storage manager role. A single instance is its own manager.
const CLUSTER = { lanes: [0, 1, 2], manager: MANAGER };
const SINGLE = { lanes: [0], manager: PRIMARY };
const CHECK_MINUTES = 5;

const UNIT_SECONDS = 2.5;
const SEC = 1 / UNIT_SECONDS;
const ANIM = { morph: 1.0 * SEC, lift: 1.5 * SEC, evict: 0.9 * SEC, lamp: 0.4 * SEC };
// The WAL stream: a segment every PERIOD, up to the store in UP, each replica fetches it.
const WAL = { period: 0.42 * SEC, up: 0.5 * SEC, wait: [0, 0.08 * SEC, 0.16 * SEC], down: 0.5 * SEC, keep: 9 };

// Calendar. Each preset's start maps to 2026-10-21; u counts partitions from there.
const two = (n) => String(n).padStart(2, "0");
const daysIn = (y, m) => new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
function dateOf(g, u) {
  const s = Math.floor(PRESETS[g].start);
  if (g === "HOUR") return new Date(Date.UTC(2026, 9, 21, 8) + (u - s) * 3600e3);
  if (g === "DAY") return new Date(Date.UTC(2026, 9, 21) + (u - s) * 86400e3);
  const m = Math.floor(u) - s + 2026 * 12 + 9;
  const y = Math.floor(m / 12), mo = m % 12;
  return new Date(Date.UTC(y, mo, 1) + (u - Math.floor(u)) * daysIn(y, mo) * 86400e3);
}
const unitsBetween = (g, a, b) => {
  if (g === "MONTH") return null;
  return (b - a) / (g === "HOUR" ? 3600e3 : 86400e3);
};

// The exact TTL of stage k for partition p, in partition widths (calendar months vary).
function ttlOf(g, k, p) {
  const end = dateOf(g, p + 1 + 1e-9);
  if (g === "HOUR") return [1, 6, 24][k];
  if (g === "DAY") {
    if (k === 0) return 1 / 24;
    if (k === 1) return 3;
    const later = Date.UTC(end.getUTCFullYear(), end.getUTCMonth() + 1, end.getUTCDate());
    return unitsBetween(g, end.getTime(), later);
  }
  if (k === 0) return 1 / daysIn(end.getUTCFullYear(), end.getUTCMonth());
  return [0, 1, 12][k];
}
// The nominal TTLs, where the marks on the floor are drawn.
const nominal = (g) => ({ HOUR: [1, 6, 24], DAY: [1 / 24, 3, 30], MONTH: [1 / 30.44, 1, 12] })[g];
const axisEnd = (g) => 2 * nominal(g)[2];

const minutesToU = (g, m) => m / PRESETS[g].minutes;
function nextCheck(g, i, t) {
  const step = minutesToU(g, CHECK_MINUTES);
  const phase = minutesToU(g, INSTANCES[i].check);
  return phase + Math.ceil((t - phase) / step - 1e-9) * step;
}
// the first WAL segment at or after t, and when instance i has applied it
const segmentAfter = (t) => Math.ceil(t / WAL.period - 1e-9);
const appliedAt = (n, i) => n * WAL.period + (i === PRIMARY ? 0 : WAL.up + WAL.wait[i] + WAL.down);

// When each thing happens to partition p, as u values. C is the cluster in the figure.
function eventsOf(g, p, C = CLUSTER) {
  const M = C.manager;
  const end = p + 1;
  const up = nextCheck(g, M, end + ttlOf(g, 0, p));
  const upDone = up + ANIM.lift;
  const conv = INSTANCES.map((_, i) => nextCheck(g, i, end + ttlOf(g, 1, p)));
  const seal = nextCheck(g, PRIMARY, end + ttlOf(g, 2, p));
  const sealSeg = segmentAfter(seal);
  const sealIn = INSTANCES.map((_, i) => (i === PRIMARY ? seal : appliedAt(sealSeg, i)));
  const sealed = nextCheck(g, M, Math.max(sealIn[M], upDone));
  const cold = INSTANCES.map((_, i) => nextCheck(g, i, sealed));
  return { end, up, upDone, conv, seal, sealSeg, sealIn, sealed, cold };
}

const unit01 = (x) => (x <= 0 ? 0 : x >= 1 ? 1 : x);
const span = (u, from, length) => unit01((u - from) / length);

function laneState(g, p, i, u, C = CLUSTER) {
  const e = eventsOf(g, p, C);
  return { active: u < e.end, m: span(u, e.conv[i], ANIM.morph), sealed: span(u, e.sealIn[i], ANIM.morph * 0.5), evict: span(u, e.cold[i], ANIM.evict) };
}
function storeState(g, p, u, C = CLUSTER) {
  const e = eventsOf(g, p, C);
  return { lift: u < e.up ? -1 : span(u, e.up, ANIM.lift), sealed: u >= e.sealed };
}
// Did an instance's policy check do work at about time u (for its lamp)?
function lampOf(g, i, u, partitions, C = CLUSTER) {
  let best = 0;
  for (const p of partitions) {
    const e = eventsOf(g, p, C);
    const times = [e.conv[i], e.cold[i]];
    if (i === C.manager) times.push(e.up, e.sealed);
    if (i === PRIMARY) times.push(e.seal);
    for (const t of times) if (u >= t && u < t + ANIM.lamp) best = Math.max(best, 1 - (u - t) / ANIM.lamp);
  }
  return best;
}

// Partitions on the benches at time u, oldest first.
function partitionsAt(g, u) {
  const out = [];
  for (let p = Math.floor(u - axisEnd(g)) - 1; p <= Math.floor(u); p++) out.push(p);
  return out;
}

function clockOf(g, u) {
  const d = dateOf(g, u + 1e-9);
  // coarse enough to read while it runs: 5 minutes for HOUR, the hour for DAY, the day for MONTH
  const day = d.getUTCFullYear() + "-" + two(d.getUTCMonth() + 1) + "-" + two(d.getUTCDate());
  if (g === "MONTH") return day;
  const min = g === "HOUR" ? Math.floor(d.getUTCMinutes() / 5) * 5 : 0;
  return day + " " + two(d.getUTCHours()) + ":" + two(min);
}
function nameOf(g, p) {
  const d = dateOf(g, p + 1e-9);
  const ym = d.getUTCFullYear() + "-" + two(d.getUTCMonth() + 1);
  if (g === "MONTH") return ym;
  if (g === "DAY") return ym + "-" + two(d.getUTCDate());
  return ym + "-" + two(d.getUTCDate()) + "T" + two(d.getUTCHours());
}
function durationOf(g, du) {
  const m = Math.max(1, Math.ceil(du * PRESETS[g].minutes - 1e-6));
  if (m <= 55) return Math.ceil(m / 5) * 5 + "m"; // the policy checks every 5 minutes
  if (m < 1440) return Math.ceil(m / 60) + "h";
  const days = Math.round(m / 1440);
  if (days < 45) return days + "d";
  return Math.round(days / 30.44) + " months";
}

// One line about partition p, for the readout.
function partitionText(g, p, u, C = CLUSTER) {
  const e = eventsOf(g, p, C);
  const name = nameOf(g, p);
  const n = C.lanes.length;
  const lanes = C.lanes.map((i) => laneState(g, p, i, u, C));
  const count = (f) => lanes.filter(f).length;
  // "on all 3" for a cluster; nothing to add for a single instance
  const all = n === 1 ? "" : " on all " + n;
  const some = (c) => (n === 1 ? "" : " on " + c + " of " + n);
  const age = u - e.end;
  const st = storeState(g, p, u, C);
  const next = PRESETS[g].stages.map(([s], k) => ({ s, at: ttlOf(g, k, p) })).filter(({ at }) => age < at).sort((a, b) => a.at - b.at)[0];
  const until = next ? " · " + next.s + " in " + durationOf(g, next.at - age) : "";
  const uploader = n === 1 ? "uploading it as Parquet" : "manager uploading it as Parquet";
  const copy = st.lift >= 1 ? "Parquet partition in the object store" : st.lift >= 0 ? uploader : "not in the object store yet";
  if (lanes[0].active) return name + " · active, native" + all + until;
  const cold = count((s) => s.evict >= 1);
  if (cold === n) return name + " · local data dropped" + all + ", _pm and index kept, reads go to the object store";
  if (cold > 0) return name + " · local data dropped" + some(cold);
  if (count((s) => s.sealed > 0) > 0) return name + (n === 1 ? " · sealed read-only, local data drops next" : " · sealed through the WAL, each instance drops its local data next");
  const parquet = count((s) => s.m >= 1);
  const local = parquet === 0 ? "native" + all : parquet === n ? "Parquet" + all : "Parquet" + some(parquet);
  return name + " · local: " + local + " · " + copy + until;
}

// The next policy work anywhere, for the idle readout.
// Every stage has its own next due time, so all three show, in policy order.
function nextWorkText(g, u) {
  return PRESETS[g].stages
    .map(([s], k) => {
      let at = Infinity;
      for (const p of partitionsAt(g, u)) {
        const t = p + 1 + ttlOf(g, k, p);
        if (t > u + 1e-9 && t < at) at = t;
      }
      return at < Infinity ? s + " in " + durationOf(g, at - u) : "";
    })
    .filter(Boolean)
    .join(" · ")
    .replace(/^/, "next: ");
}

// Geometry shared by the build (rest pose) and the live code (every frame).
// `k` is the iso kit, `G` the lathe kit, `P` the projection.
//
// The x axis is partition age on a log scale, like a slide rule: the write head of every
// instance stands at X_NOW, and a moment that is `age` partitions old sits at
// X_NOW - S * ln(1 + age / a0). That fits TO REMOTE 1 HOUR and DROP LOCAL 1 MONTH on
// one bench. Instances are benches side by side along y; the object store is one deck
// behind them all, with the cold Parquet copies on the left and the replication bay,
// where WAL segments pass from the primary to the replicas, on the right.



const X_NOW = 156;
const X_END = -128;
const LANE_Y = [44, 0, -44]; // primary, replica 1, replica 2 (manager)
const BENCH = { x: -134, w: 330, d: 32, r: 3, t: 5, foot: 5 };
const HEAD = { x: 158, w: 36, d: 28, h: 16 };
const FLOOR = -BENCH.t - BENCH.foot;
const DECK = { x: -138, y: -104, w: 348, d: 30, r: 2, z: 47, t: 3 };
const DECK_TOP = DECK.z + DECK.t;
const BAY_X = 160; // the replication bay starts here
const STORE_Y = DECK.y + DECK.d / 2;
const ROD_Z = DECK_TOP + 2.2;
const FLY_Z = 64;
const FEED = { y: LANE_Y[0] - 5, x0: HEAD.x + HEAD.w, x1: HEAD.x + HEAD.w + 30, z: 9 };
const RULER = { x: BENCH.x + 4, y: LANE_Y[0] + BENCH.d / 2 + 4, w: X_NOW - BENCH.x + 2, d: 15, r: 1 };

// The slide-rule axis for a preset.
function axisOf(g) {
  const a0 = PRESETS[g].a0;
  const S = (X_NOW - X_END) / Math.log(1 + axisEnd(g) / a0);
  const xOfAge = (age) => X_NOW - S * Math.log(1 + Math.max(0, age) / a0);
  return { S, xOfAge, gates: nominal(g).map(xOfAge) };
}

// A block's cross-section, back (toward the store) to front: the symbol index .k/.v,
// then one bar per column file: ts 8, symbol key 4, price 8, amount 8, venue data
// about 10 (average string) and venue aux 16 bytes per row.
const INDEX = [2, 3];
const DATA = [8, 4, 8, 8, 10, 16];
const HALF = 12;
const GAP = 0.6;
const PER_BYTE = (2 * HALF - GAP * (INDEX.length + DATA.length - 1)) / (INDEX.reduce((a, b) => a + b, 0) + DATA.reduce((a, b) => a + b, 0));
const PALLET = 1.2;
const BAR_H = 8;
const INDEX_H = 2.4;
const RATIO = 0.45;
const POST_Y = 4.5;
const POST_TOP = PALLET + 10;
const DETAIL = 9; // below this length a block drops its fine detail
const ROW_GROUPS = 4; // row groups per Parquet partition, as drawn
// Parquet is the one coloured thing: local Parquet, _pm and every copy in the store.
const PQ = { tone: "blue", crease: "lo", className: "sa-pq" };
const PQ_CSS =
  ".sa-fig .sa-pq>.iso-top{fill:color-mix(in srgb,var(--anatomy-blue) 30%,var(--anatomy-top))}" +
  ".sa-fig .sa-pq>.iso-shade{fill:color-mix(in srgb,var(--anatomy-blue) 18%,var(--anatomy-shade-2))}" +
  ".sa-fig .sa-pq>.iso-fill{fill:color-mix(in srgb,var(--anatomy-blue) 18%,var(--anatomy-face))}" +
  // _pm, the Parquet metadata, is solid blue so it reads apart from the data it describes
  ".sa-fig .sa-pm>.iso-top{fill:color-mix(in srgb,var(--anatomy-blue) 85%,var(--anatomy-top))}" +
  ".sa-fig .sa-pm>.iso-shade{fill:color-mix(in srgb,var(--anatomy-blue) 65%,var(--anatomy-shade-2))}" +
  ".sa-fig .sa-pm>.iso-fill{fill:color-mix(in srgb,var(--anatomy-blue) 65%,var(--anatomy-face))}" +
  ".sa-fig .sa-read>.iso-top{fill:var(--anatomy-lit)}.sa-fig .sa-read>.iso-shade,.sa-fig .sa-read>.iso-fill{fill:color-mix(in srgb,var(--anatomy-lit) 60%,var(--anatomy-face))}" +
  ".sa-fig .sa-label{font:600 9.5px/1 var(--anatomy-mono);letter-spacing:.03em;fill:var(--anatomy-strong);stroke:var(--anatomy-card);stroke-width:3.4px;stroke-linejoin:round;paint-order:stroke;pointer-events:none}" +
  ".sa-fig .sa-label[data-sub]{font-weight:400;font-size:8.6px;fill:var(--anatomy-text)}";

function makeParts(k, G, P) {
  const S = (paths, style) => k.solidSvg(paths, style);
  const L = (d, style) => k.lineSvg(d, style);
  const D = (points, style) => k.dotsSvg(points, style);
  const at = (point) => k.iso(point, P);
  const slab = (plan, z, h, style, steps = 2, bevel = 0.25) => S(k.slabOf(plan, z, h, P, steps, Math.max(0.05, Math.min(bevel, h / 3, plan.w / 3))), style);
  const text = (m, s, opts) => k.faceTextSvg(m, s, opts);

  // One partition on one instance, built with its older end at x = 0.
  // m: Parquet 0..1. sealed, evict: 0..1. open: the active partition (runs into the head).
  // cols: optional six flags, one per column-file bar, so a query lights only what it reads.
  function blockSvg(len, { m = 0, sealed = 0, evict = 0, lit = false, open = false, cols = null } = {}) {
    const out = [];
    const fine = len >= DETAIL;
    const tone = { tone: "hi", crease: "lo", lit };
    const pq = { ...PQ, lit };
    const end = Math.min(0.8, len * 0.08);
    out.push(slab({ x: 0, y: -HALF - 0.6, w: len, d: 2 * HALF + 1.2, r: Math.min(0.6, len / 4) }, 0, PALLET, { tone: "lo", crease: "none" }));
    // _pm stays visible at any width: it is all that is left locally after DROP LOCAL
    const pmW = fine ? 1.4 * m : m >= 1 ? Math.min(1.2, len * 0.35) : 0;
    const x0 = end, x1 = open ? len : len - end - (pmW ? pmW + 0.4 : 0);
    // _pm, the Parquet metadata, stands at the newer end once the partition is Parquet
    const pm = () => {
      if (pmW <= 0.02) return "";
      const pmH = (BAR_H * RATIO + 1.2) * m;
      const plan = { x: len - end - pmW, y: -HALF, w: pmW, d: 2 * HALF, r: Math.min(0.2, pmW / 3) };
      let s = slab(plan, PALLET, pmH, { ...pq, className: "sa-pm" });
      if (sealed > 0 && fine) {
        s += slab({ x: plan.x - 0.5, y: -2.2, w: pmW + 1, d: 4.4, r: 0.4 }, PALLET + pmH, 1.2 * sealed, { tone: "mid", crease: "lo", lit });
        s += D([at([plan.x + pmW / 2, 0, PALLET + pmH + 1.2 * sealed])], { size: 0.45, tone: lit ? "hi" : "mid" });
      }
      return s;
    };
    if (x1 - x0 < 0.3) return out.join("") + pm();
    // the symbol index stays on every instance, through every stage
    const idxD = INDEX.reduce((a, b) => a + b * PER_BYTE, 0) + GAP;
    if (fine) {
      let y = -HALF;
      for (const bytes of INDEX) { out.push(slab({ x: x0, y, w: x1 - x0, d: bytes * PER_BYTE, r: 0.3 }, PALLET, INDEX_H, tone)); y += bytes * PER_BYTE + GAP; }
    } else out.push(slab({ x: x0, y: -HALF, w: x1 - x0, d: idxD - GAP, r: 0.2 }, PALLET, INDEX_H, tone));
    const dataY0 = -HALF + idxD;
    const h = BAR_H * (1 - (1 - RATIO) * m);
    let body = "";
    if (m < 1 && fine) {
      // native: one bar per column file, the gaps closing as it binds into Parquet
      const gap = GAP * (1 - m);
      let y = dataY0;
      DATA.forEach((bytes, i) => {
        const w = bytes * PER_BYTE + ((GAP - gap) * (DATA.length - 1)) / DATA.length;
        const on = lit && (!cols || cols[i]);
        body += slab({ x: x0, y, w: x1 - x0, d: w, r: 0.3 }, PALLET, h, { ...(m >= 0.5 ? pq : tone), lit: on });
        y += w + gap;
      });
    } else {
      const plan = { x: x0, y: dataY0, w: x1 - x0, d: HALF - dataY0, r: Math.min(0.4, (x1 - x0) / 4) };
      const top = PALLET + h;
      if (m < 1) {
        // a thin native block: the column files show as lines along its top
        let seams = "";
        let yy = dataY0;
        DATA.slice(0, -1).forEach((bytes) => { yy += bytes * PER_BYTE + GAP; seams += k.lineOnTop([x0 + 0.2, yy], [x1 - 0.2, yy], top, P); });
        body += S(k.slabOf(plan, PALLET, h, P, 2, 0.15), { ...tone, inner: L(seams, { tone: "lo" }) });
      } else {
        let groups = "";
        if (fine) for (let n = 1; n < 4; n++) groups += k.lineOnTop([x0 + ((x1 - x0) * n) / 4, dataY0 + 0.6], [x0 + ((x1 - x0) * n) / 4, HALF - 0.6], top, P);
        body += S(k.slabOf(plan, PALLET, h, P, 2, 0.2), { ...pq, inner: groups ? L(groups, { tone: "blue" }) : "" });
      }
    }
    if (evict < 1) out.push(evict > 0 ? `<g opacity="${(1 - evict).toFixed(3)}">${body}</g>` : body);
    else if (fine) out.push(L(k.planOutline({ x: x0, y: dataY0, w: x1 - x0, d: HALF - dataY0, r: 0.4 }, PALLET, P, 2), { tone: "lo" }));
    out.push(pm());
    return out.join("");
  }

  // The Parquet copy in the object store: data.parquet with its _pm, on a pad.
  function copySvg(len, z0, lit, pad = true) {
    const out = [];
    const tone = { ...PQ, lit };
    const fine = len >= DETAIL;
    const end = Math.min(0.8, len * 0.08);
    if (pad) out.push(slab({ x: 0, y: -HALF + 3, w: len, d: 2 * HALF - 3, r: Math.min(0.6, len / 4) }, z0, 0.8, { tone: "lo", crease: "none" }));
    const zb = z0 + (pad ? 0.8 : 0);
    const x0 = end, x1 = len - end - (fine ? 1.8 : 0);
    if (x1 - x0 < 0.3) return out.join("");
    const y0 = -HALF + 3.6;
    const h = BAR_H * RATIO;
    let groups = "";
    if (fine) for (let n = 1; n < 4; n++) groups += k.lineOnTop([x0 + ((x1 - x0) * n) / 4, y0 + 0.6], [x0 + ((x1 - x0) * n) / 4, HALF - 0.6], zb + h, P);
    out.push(S(k.slabOf({ x: x0, y: y0, w: x1 - x0, d: HALF - y0, r: Math.min(0.4, (x1 - x0) / 4) }, zb, h, P, 2, 0.2), { ...tone, inner: groups ? L(groups, { tone: "blue" }) : "" }));
    if (fine) out.push(slab({ x: len - end - 1.4, y: y0, w: 1.4, d: HALF - y0, r: 0.2 }, zb, h + 1.2, { ...tone, className: "sa-pm" }));
    return out.join("");
  }

  // A cold partition reads its data from the object store: a rod from the copy forward
  // over the benches, with a drop to each instance that has dropped its local data.
  function rodSvg(cx, lanes, lit) {
    if (!lanes.length) return "";
    const front = Math.max(...lanes.map((i) => LANE_Y[i])) + POST_Y;
    let drops = "", posts = "";
    for (const i of lanes) {
      drops += k.segment([cx, LANE_Y[i] + POST_Y, ROD_Z], [cx, LANE_Y[i] + POST_Y, POST_TOP], P);
      posts += S(k.cylinder(cx, LANE_Y[i] + POST_Y, 0.9, PALLET, POST_TOP - PALLET, P, 14), { tone: "mid", lit });
    }
    return posts + L(drops, { tone: lit ? "lit" : "lo" }) + L(k.segment([cx, STORE_Y + HALF, ROD_Z], [cx, front, ROD_Z], P), { tone: lit ? "lit" : "mid" }) +
      D([at([cx, STORE_Y + HALF, ROD_Z]), ...lanes.flatMap((i) => [at([cx, LANE_Y[i] + POST_Y, ROD_Z]), at([cx, LANE_Y[i] + POST_Y, POST_TOP])])], { size: 0.55, tone: lit ? "hi" : "mid" });
  }

  const ease = (x) => x * x * (3 - 2 * x);
  // up, across, down: the path anything takes between a bench and the deck
  function flight(a, b, s) {
    if (s < 0.3) return [a[0], a[1], a[2] + (FLY_Z - a[2]) * ease(s / 0.3)];
    if (s < 0.7) { const t = ease((s - 0.3) / 0.4); return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, FLY_Z]; }
    return [b[0], b[1], FLY_Z + (b[2] - FLY_Z) * ease((s - 0.7) / 0.3)];
  }

  // A WAL segment: a small cartridge, far smaller than any partition.
  function chipSvg([x, y, z], lit) {
    return slab({ x: x - 1.8, y: y - 1.4, w: 3.6, d: 2.8, r: 0.4 }, z, 1.6, { tone: "hi", crease: "lo", lit }, 2, 0.2);
  }
  // Rows from clients riding the duct into the primary: small blocks, always moving.
  function feedSvg(u) {
    const { y, x0, x1, z } = FEED;
    let out = "";
    for (let j = 0; j < 5; j++) {
      const s = (((u * 1.6 + j / 5) % 1) + 1) % 1;
      const x = x1 - 1.6 - s * (x1 - x0 - 3.2);
      const fade = s > 0.88 ? (1 - s) / 0.12 : s < 0.1 ? s / 0.1 : 1;
      out += `<g opacity="${fade.toFixed(2)}">${slab({ x: x - 0.9, y: y - 1.1, w: 1.8, d: 2.2, r: 0.3 }, z, 1.3, { tone: "hi", crease: "lo" }, 2, 0.2)}</g>`;
    }
    return out;
  }
  const PORT = (i) => [HEAD.x + 29, LANE_Y[i] - 7, HEAD.h + 0.6];
  const baySlot = (n) => [DECK.x + DECK.w - 5 - n * 5, STORE_Y + 2, DECK_TOP];

  // The clock on the primary: one turn of the hand per partition.
  const CLOCK = { x: 185, y: LANE_Y[0] + 6, r: 6, z: HEAD.h };
  function dialSvg(ticksPerTurn) {
    const { x, y, r, z } = CLOCK;
    const out = [];
    out.push(S(k.cylinder(x, y, r + 1.3, z, 1, P, 40), { tone: "lo" }));
    out.push(S(k.cylinder(x, y, r, z + 1, 1.6, P, 48, 0.4), { tone: "hi", crease: "lo" }));
    out.push(L(k.ring(x, y, r - 0.9, z + 2.6, P, 48), { tone: "lo" }));
    const every = ticksPerTurn % 4 === 0 ? ticksPerTurn / 4 : ticksPerTurn;
    const ticks = k.radialTicks(x, y, r - 1, ticksPerTurn, every, z + 2.6, [0.7, 1.6], P);
    out.push(L(ticks.minor, { tone: "lo" }), L(ticks.major, { tone: "mid" }));
    return out.join("");
  }
  function handPath(fraction) {
    const a = fraction * Math.PI * 2;
    const { x, y, r, z } = CLOCK;
    return k.lineOnTop([x - Math.sin(a) * 1.2, y + Math.cos(a) * 1.2], [x + Math.sin(a) * (r - 2), y - Math.cos(a) * (r - 2)], z + 2.7, P);
  }
  const hubSvg = () => D([at([CLOCK.x, CLOCK.y, CLOCK.z + 2.7])], { size: 0.6, tone: "hi" });

  // The lamp on each head lights while that instance's policy check does work.
  const LAMP = (i) => ({ x: HEAD.x + 22, y: LANE_Y[i] - 9.5 });
  function lampSvg(i, glow) {
    const { x, y } = LAMP(i);
    return S(k.cylinder(x, y, 1.7, HEAD.h, 1.6, P, 20), { tone: glow > 0.05 ? "hi" : "mid", lit: glow > 0.05 }) + D([at([x, y, HEAD.h + 1.6])], { size: 0.5 + glow * 0.5, tone: glow > 0.05 ? "hi" : "lo" });
  }

  // The marks on each bench for a preset: a line across, a stop at the back, a stop at the
  // front, and the stage engraved on the front margin, ending at the line.
  // only: which stages to mark (indices into the policy), so a figure can show just some
  function marksBack(i, g, only = [0, 1, 2]) {
    const gates = only.map((n) => axisOf(g).gates[n]);
    const y0 = LANE_Y[i] - BENCH.d / 2, y1 = y0 + BENCH.d;
    let out = L(gates.map((x) => k.lineOnTop([x, y0 + 2.2], [x, y1 - 2.2], 0, P)).join(""), { tone: "mid" });
    for (const x of gates) out += slab({ x: x - 1.4, y: y0 + 0.6, w: 2.8, d: 1.8, r: 0.4 }, 0, 2, { tone: "hi", crease: "lo" }, 2, 0.3);
    return out;
  }
  function marksFront(i, g, only = [0, 1, 2]) {
    const gates = only.map((n) => axisOf(g).gates[n]);
    const y1 = LANE_Y[i] + BENCH.d / 2;
    return gates.map((x) => slab({ x: x - 1.4, y: y1 - 2.4, w: 2.8, d: 1.8, r: 0.4 }, 0, 2, { tone: "hi", crease: "lo" }, 2, 0.3)).join("");
  }

  // The ruler on the floor in front: a tick per partition boundary, a stop and the stage
  // with its TTL at each mark, and what the partition is between the marks.
  function rulerSvg(g, only = [0, 1, 2]) {
    const { xOfAge } = axisOf(g);
    const gates = only.map((n) => axisOf(g).gates[n]);
    const out = [];
    const R = RULER, z = FLOOR + 0.8;
    out.push(slab(R, FLOOR, 0.8, { tone: "lo", crease: "none" }, 3));
    const minor = [];
    let last = Infinity;
    for (let n = 1; n <= Math.ceil(axisEnd(g)); n++) {
      const x = xOfAge(n);
      if (last - x < 1.1) continue;
      minor.push(k.lineOnTop([x, R.y + 0.8], [x, R.y + 2.6], z, P));
      last = x;
    }
    out.push(L(minor.join(""), { tone: "lo" }));
    out.push(L(gates.map((x) => k.lineOnTop([x, R.y + 0.8], [x, R.y + 5.2], z, P)).join(""), { tone: "hi" }));
    out.push(D([at([X_NOW, R.y + 1.6, z])], { size: 0.6, tone: "hi" }));
    out.push(L(gates.map((x) => k.lineOnTop([x, R.y + 5.2], [x, R.y + R.d - 1.2], z, P)).join(""), { tone: "mid" }));
    out.push(D(gates.map((x) => at([x, R.y + R.d - 1.2, z])), { size: 0.6, tone: "hi" }));
    return out.join("");
  }

  // Words stay upright and screen-sized, with a halo, so they read at any theme: a
  // label is anchored to a world point and offset in screen px.
  const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");
  function label(pt, s, { anchor = "middle", dx = 0, dy = 0, sub = false } = {}) {
    const [x, y] = at(pt);
    return `<text class="sa-label"${sub ? ' data-sub=""' : ""} x="${(x + dx).toFixed(1)}" y="${(y + dy).toFixed(1)}" text-anchor="${anchor}">${esc(s)}</text>`;
  }
  // The labels that depend on the policy: each mark with its TTL, what the local copy is
  // between the marks, and where the Parquet copies begin on the deck.
  // uploader: who puts the Parquet partitions in the object store, for the deck caption
  function labelsSvg(g, { uploader = "uploaded once, only by replica 2" } = {}) {
    const { gates } = axisOf(g);
    const R = RULER, z = FLOOR;
    const out = [];
    // Each mark gets its name and what happens there, centred under its tick. The ruler
    // falls to the right, so neighbouring marks stack rather than collide.
    const what = [
      ["Parquet partition to the object store", "local copy stays native"],
      ["local copy becomes Parquet"],
      ["local keeps metadata only"],
    ];
    // Laid out from the heads leftwards: each label keeps clear of the heads and of the
    // label before it, sliding left along the ruler; a slid label gets a leader to its mark.
    const GAP = 56;
    let limit = X_NOW - GAP;
    const leaders = [], pins = [];
    PRESETS[g].stages.forEach(([s, , short], n) => {
      const x = Math.min(gates[n], limit);
      limit = x - GAP;
      if (gates[n] - x > 2) {
        leaders.push(k.lineOnTop([gates[n], R.y + R.d - 1.2], [x, R.y + R.d - 1.2], z + 0.8, P));
        pins.push(at([x, R.y + R.d - 1.2, z + 0.8]));
      }
      const pt = [x, R.y + R.d, z];
      out.push(label(pt, s + " " + short, { dy: 13 }));
      what[n].forEach((line, j) => out.push(label(pt, line, { dy: 24 + j * 10, sub: true })));
    });
    if (leaders.length) out.unshift(L(leaders.join(""), { tone: "mid" }) + D(pins, { size: 0.6, tone: "hi" }));
    const cold = (X_END + gates[0]) / 2;
    out.push(label([cold, DECK.y + DECK.d, DECK.z], "PARQUET PARTITIONS", { dy: 13 }));
    out.push(label([cold, DECK.y + DECK.d, DECK.z], uploader, { dy: 25, sub: true }));
    return out.join("");
  }

  // What a query reads from one partition, drawn on top of it in the partition's own frame.
  // Native: the stretch of each selected column file it scans. Parquet, local or in the
  // object store: the column chunks of every row group that overlaps the time range, which
  // the _pm metadata maps to byte ranges inside data.parquet. f0..f1 is the queried part of
  // the partition's time span (0 = its start); bars flags the six column-file bars.
  function readSvg(len, { form, f0 = 0, f1 = 1, bars, open = false, z0 = 0 }) {
    const style = { tone: "lit", crease: "lo", lit: true, className: "sa-read" };
    const end = Math.min(0.8, len * 0.08);
    const idxD = INDEX.reduce((a, b) => a + b * PER_BYTE, 0) + GAP;
    const out = [];
    const cell = (xa, xb, ya, yb, z) => {
      if (xb - xa < 0.12 || yb - ya < 0.2) return;
      out.push(slab({ x: xa, y: ya, w: xb - xa, d: yb - ya, r: Math.min(0.25, (xb - xa) / 3) }, z, 0.8, style, 2, 0.15));
    };
    if (form === "native") {
      const x0 = end, x1 = open ? len : len - end;
      const xa = x0 + (x1 - x0) * f0, xb = x0 + (x1 - x0) * f1;
      let y = -HALF + idxD;
      DATA.forEach((bytes, i) => {
        const w = bytes * PER_BYTE;
        if (bars[i]) cell(xa + 0.2, xb - 0.2, y + 0.15, y + w - 0.15, PALLET + BAR_H);
        y += w + GAP;
      });
      return out.join("");
    }
    const remote = form === "copy";
    const fine = len >= DETAIL;
    const x0 = end, x1 = len - end - (remote ? (fine ? 1.8 : 0) : fine ? 1.8 : Math.min(1.2, len * 0.35) + 0.4);
    const y0 = remote ? -HALF + 3.6 : -HALF + idxD;
    const scale = (HALF - y0) / DATA.reduce((a, b) => a + b * PER_BYTE, 0);
    const top = remote ? z0 + 0.8 + BAR_H * RATIO : PALLET + BAR_H * RATIO;
    // the row groups that overlap the range; on a narrow partition they merge into one cell
    const hit = [];
    for (let g = 0; g < ROW_GROUPS; g++) if ((g + 1) / ROW_GROUPS > f0 && g / ROW_GROUPS < f1) hit.push(g);
    if (!hit.length) return "";
    const per = (x1 - x0) / ROW_GROUPS;
    const spans = per >= 1.6 ? hit.map((g) => [g, g + 1]) : [[hit[0], hit[hit.length - 1] + 1]];
    const inset = Math.min(0.35, per * 0.15);
    for (const [g0, g1] of spans) {
      const xa = x0 + per * g0 + inset, xb = x0 + per * g1 - inset;
      let y = y0;
      DATA.forEach((bytes, i) => {
        const w = bytes * PER_BYTE * scale;
        if (bars[i]) cell(xa, xb, y + 0.2, y + w - 0.2, top);
        y += w;
      });
    }
    return out.join("");
  }

  // The tiers along the ruler, for figures about reading: a query's read path changes at
  // TO PARQUET (native to Parquet) and at DROP LOCAL (local to cold), not at TO REMOTE.
  function tiersSvg(g) {
    const { gates } = axisOf(g);
    const R = RULER, z = FLOOR;
    const zones = [["NATIVE", gates[1], X_NOW], ["PARQUET", gates[2], gates[1]], ["COLD", R.x, gates[2]]];
    return zones.map(([s, a, b]) => label([(a + b) / 2, R.y + R.d, z], s, { dy: 13 })).join("");
  }

  return { blockSvg, copySvg, readSvg, rodSvg, flight, chipSvg, feedSvg, PORT, baySlot, dialSvg, handPath, hubSvg, lampSvg, marksBack, marksFront, rulerSvg, labelsSvg, tiersSvg, label, CLOCK, slab };
}

const BLOCK = { HALF, PALLET, BAR_H };

// The model behind Fig 5: failover with a store-and-forward client, as a small scripted
// simulation. The client, the three nodes and the object store follow their own rules;
// an operator's commands are the script. Each run is recorded once, so the drawing is a
// pure function of time and the loop replays it exactly.
//
// From the failover, SWITCH ROLE, client failover and store-and-forward docs, and the
// uploader (wal/uploader/indexer.rs):
//   - The client keeps every frame it has not had acknowledged in its store-and-forward
//     ring. Plain ACK: acknowledged once committed to the primary's WAL. Durable ACK
//     (request_durable_ack=on): only once that WAL is in the object store.
//   - The primary uploads every throttle window (1 s, the default); replicas poll the
//     index every second and apply what landed.
//   - SWITCH ROLE TO REPLICA refuses new writes, drains writers, uploads what is still
//     pending, and becomes a replica that follows the store. It never abandons committed
//     transactions. A QWP client is closed on its first refused frame, after its durable
//     acks have been flushed; that frame is replayed later.
//   - SWITCH ROLE TO PRIMARY is accepted once the node has applied everything in the store;
//     until then it answers 421 PRIMARY_CATCHUP. It claims the store by writing
//     index.msgpack with the next sync_id.
//   - A primary that dies takes its unuploaded transactions with it. Once repaired it is
//     started with replication.role=replica and rejoins as a replica.
//   - The client walks its host list with backoff (100 ms doubling, at most 5 s): a replica
//     answers 421 REPLICA, a node that is down does not answer. After connecting it replays
//     everything past its acknowledged watermark. A frame already in the store arrives
//     twice, and DEDUP drops it.

const RATE = 0.1; // a frame every 100 ms
const WINDOW = 1; // throttle window, the default
const UPLOAD = 0.15;
const NET = 0.05;
const POLL = 1;
const PHASE = [0, 0.08, 0.17]; // each node polls on its own clock
const REPLAY_GAP = 0.025; // the backlog goes out back to back
const RESTART = 3; // seconds a node is down for maintenance or repair
const SYNC_ID = 42;
const STEP = 0.01;

const VIS = { wire: 0.35, ack: 0.3, upload: 0.45, down: 0.4, flash: 0.6, command: 2.2 };

const MODES = {
  durable: { label: "DURABLE ACK", note: "acknowledged once the WAL is in the object store" },
  plain: { label: "PLAIN ACK", note: "acknowledged once committed to the primary's WAL" },
};
const MODE_ORDER = ["durable", "plain"];

// The operator's script for each scenario: [time, command, node].
const SCENARIOS = {
  planned: {
    label: "PLANNED SWITCHOVER",
    loop: 32,
    script: [
      [6, "demote", 0],
      [8, "promote", 1],
      [13, "stop", 0], // maintenance: a restart to apply an update
      [13 + RESTART, "start", 0], // back as a replica (replication.role=replica)
      [21, "demote", 1],
      [23, "promote", 0],
    ],
  },
  unplanned: {
    label: "UNPLANNED FAILURE",
    loop: 28,
    script: [
      [7.88, "fail", 0], // late in a throttle window, so its last commits are in no upload
      [11, "promote", 1],
      [19, "start", 0], // repaired, started with replication.role=replica
    ],
  },
};
const SCENARIO_ORDER = ["planned", "unplanned"];

function simulate(scenarioKey, mode) {
  const sc = SCENARIOS[scenarioKey];
  const loop = sc.loop;
  const nodes = [0, 1, 2].map((i) => ({ i, role: i === 0 ? "primary" : "replica", applied: -1, committed: new Set(), pendingFrom: null, lastUp: -1 }));
  const store = { high: -1 };
  let syncId = SYNC_ID, owner = 0;
  const rec = { frames: [], sends: [], acks: [], ups: [], downs: [], attempts: [], commands: [], snaps: [], dups: [], lost: [], neverUploaded: 0, refused: [] };
  const client = { conn: null, sentTo: -1, acked: -1, nextTry: null, backoff: 0.1, plainAcked: new Set(), lastSend: undefined };
  const pendingAcks = []; // { t, n, from, cumulative }
  const inflight = []; // frames on the wire: { n, to, arrive }
  const script = [...sc.script];

  // frames arrive in order on one connection, so a node's highest commit is its tip; a gap
  // below it is frames lost with a failed primary, never to be filled
  const highCommitted = (node) => { let h = store.high; for (const x of node.committed) h = Math.max(h, x); return h; };
  const durable = new Set(); // frames that reached the object store
  const commitOn = (node, n, t) => {
    if (store.high >= n || node.committed.has(n)) { rec.dups.push({ n, t, at: node.i }); return "dup"; }
    node.committed.add(n);
    if (node.pendingFrom === null) node.pendingFrom = t;
    if (mode === "plain") pendingAcks.push({ t: t + NET, n, from: node.i });
    return "ok";
  };
  const upload = (node, t) => {
    const to = highCommitted(node);
    if (to <= Math.max(node.lastUp, store.high)) return null;
    const u = { t0: t, land: t + UPLOAD, to, from: node.i };
    node.lastUp = to;
    node.pendingFrom = null;
    rec.ups.push(u);
    return u;
  };
  const close = (t) => { client.conn = null; client.nextTry = t + NET; client.backoff = 0.1; };
  let replayTo = -1; // the last frame buffered when the client reconnected
  const isReplay = (x) => x <= replayTo;

  // the client connects to the primary at the start
  client.conn = 0;
  for (let k = 0; k <= Math.round(loop / STEP); k++) {
    const t = Math.round(k * STEP * 100) / 100;
    // the operator
    while (script.length && script[0][0] <= t + 1e-9) {
      const [, cmd, i] = script.shift();
      const node = nodes[i];
      rec.commands.push({ t, cmd, node: i });
      if (cmd === "demote") { node.role = "demoting"; const u = upload(node, t); node.drainUntil = (u ? u.land : t) + 2 * NET; }
      if (cmd === "promote") { node.role = "promoting"; node.promoteAt = t; }
      if (cmd === "fail") {
        node.role = "down";
        rec.neverUploaded = highCommitted(node) - store.high;
        rec.failedCommits = highCommitted(node);
        rec.ups = rec.ups.filter((u) => !(u.from === i && u.land > t)); // a dying primary finishes nothing
        node.committed = new Set();
        node.pendingFrom = null;
        if (client.conn === i) close(t);
      }
      if (cmd === "stop") node.role = "down";
      if (cmd === "start") { node.role = "replica"; node.committed = new Set(); node.pendingFrom = null; }
    }
    // uploads landing
    for (const u of rec.ups) {
      if (u.landed || u.land > t + 1e-9) continue;
      u.landed = true;
      store.high = Math.max(store.high, u.to);
      for (const x of nodes[u.from].committed) if (x <= u.to) durable.add(x);
      if (mode === "durable") pendingAcks.push({ t: t + NET, n: u.to, from: u.from, cumulative: true });
    }
    for (const node of nodes) {
      // a demoting primary closes its client once its durable acks are out, then follows the store
      if (node.role === "demoting" && t >= node.drainUntil - 1e-9) {
        node.role = "replica";
        node.applied = Math.max(node.applied, store.high);
        if (client.conn === node.i) close(t);
      }
      // a promotion completes once the node has applied everything in the store
      if (node.role === "promoting" && node.applied >= store.high && t >= node.promoteAt + 0.3 - 1e-9) {
        node.role = "primary";
        node.lastUp = store.high;
        syncId++;
        owner = node.i;
        rec.commands.push({ t, cmd: "owned", node: node.i });
      }
      // the primary's throttle window
      if (node.role === "primary" && node.pendingFrom !== null && t - node.pendingFrom >= WINDOW - 1e-9) upload(node, t);
      // replicas, and a node catching up for promotion, poll the index on their own clock
      const onPoll = Math.abs(((t - PHASE[node.i]) / POLL) - Math.round((t - PHASE[node.i]) / POLL)) < STEP / 2;
      if ((node.role === "replica" || node.role === "promoting") && onPoll && store.high > node.applied) {
        rec.downs.push({ t, node: node.i, to: store.high });
        node.applied = store.high;
      }
    }
    // the client produces a frame every RATE
    if (Math.abs(t / RATE - Math.round(t / RATE)) < STEP / RATE / 2) rec.frames.push({ n: rec.frames.length, p: t });
    // frames arriving at a node
    for (const f of inflight) {
      if (f.done || f.arrive > t + 1e-9) continue;
      f.done = true;
      const node = nodes[f.to];
      if (node.role === "primary") f.result = commitOn(node, f.n, t);
      else {
        f.result = "refused";
        rec.refused.push({ n: f.n, t, at: f.to });
        if (client.conn === f.to && node.role !== "demoting") close(t);
      }
    }
    // acks arriving at the client: plain ones per frame, durable ones cumulative per upload
    for (const a of pendingAcks) {
      if (a.done || a.t > t + 1e-9) continue;
      a.done = true;
      if (nodes[a.from].role === "down") continue; // it never left
      rec.acks.push({ t: a.t, from: a.from });
      if (a.cumulative) client.acked = Math.max(client.acked, a.n);
      else { client.plainAcked.add(a.n); while (client.plainAcked.has(client.acked + 1)) client.acked++; }
    }
    // the client's connection: send what has not been sent on it, or try to reconnect
    if (client.conn !== null && nodes[client.conn].role === "down") close(t);
    if (client.conn !== null && nodes[client.conn].role !== "demoting") {
      const last = rec.frames.length - 1;
      const gap = client.sentTo + 1 <= last && isReplay(client.sentTo + 1) ? REPLAY_GAP : 0;
      if (client.sentTo < last && (client.lastSend === undefined || t - client.lastSend >= gap - 1e-9)) {
        client.sentTo++;
        client.lastSend = t;
        inflight.push({ n: client.sentTo, to: client.conn, arrive: t + NET });
        rec.sends.push({ n: client.sentTo, to: client.conn, t, replay: isReplay(client.sentTo) });
      }
    } else if (client.conn === null && client.nextTry !== null && t >= client.nextTry - 1e-9) {
      let connected = false, transient = false;
      for (const node of nodes) {
